if($path==='/catalogs/save'&&$method==='POST'){require_manage();verify_csrf();$type=in_array($_POST['catalog_type']??'',['sector','location','asset_status','windows_version'],true)?$_POST['catalog_type']:'sector';try{query('INSERT INTO catalog_items(company_id,catalog_type,name) VALUES(?,?,?)',[tenant_id(),$type,trim($_POST['name'])]);flash('success','Item cadastrado.');}catch(Throwable){flash('error','Este item já existe.');}redirect('/catalogs');}
