if($path==='/fields/save'&&$method==='POST'){require_manage();verify_csrf();$n=trim($_POST['name']);$key=trim(preg_replace('/[^a-z0-9]+/','_',strtolower(iconv('UTF-8','ASCII//TRANSLIT',$n))),'_');$opts=array_values(array_filter(array_map('trim',preg_split('/\R/',$_POST['options']??''))));try{query('INSERT INTO custom_fields(company_id,name,field_key,field_type,options_json) VALUES(?,?,?,?,?)',[tenant_id(),$n,$key,$_POST['field_type'],json_encode($opts,JSON_UNESCAPED_UNICODE)]);flash('success','Campo criado.');}catch(Throwable){flash('error','Campo duplicado.');}redirect('/fields');}
