n></div></form><?php page_end();exit;}
if($path==='/settings/save'&&$method==='POST'){require_manage();verify_csrf();$logo=company()['logo_path'];if(!empty($_FILES['logo']['tmp_name'])){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['logo']['tmp_name']);$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$mime]??null;if(!$ext||$_FILES['logo']['size']>2000000){flash('error','Logo inválido.');redirect('/settings');}$name='company-'.tenant_id().'-'.bin2hex(random_bytes(4)).'.'.$ext;move_uploaded_file($_FILES['logo']['tmp_name'],dirname(__DIR__).'/storage/uploads/'.$name);$logo='/media/'.$name;}query('UPDATE companies SET name=?,logo_path=?,primary_color=?,accent_color=?,critical_year_before=?,critical_ram_below=?,attention_score_threshold=?,critical_score_threshold=?,ssd_mitigation_points=? WHERE id=?',[trim($_POST['name']),$logo,$_POST['primary_color'],$_POST['accent_color'],(int)$_POST['critical_year_before'],(int)$_POST['critical_ram_below'],max(1,(int)$_POST['attention_score_threshold']),max(2,(int)$_POST['critical_score_threshold']),max(0,(int)$_POST['ssd_mitigation_points']),tenant_id()]);refresh_company();flash('success','Empresa e critérios atualizados.');redirect('/settings');}
